(function(){'use strict';
const KEY='nawaf-hq-v5';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot',"'":'&#39;'}[m]))}
function age(v){const t=Date.parse(v||'');if(!Number.isFinite(t))return '';const m=Math.max(1,Math.floor((Date.now()-t)/60000));if(m<60)return `منذ ${m} د`;const h=Math.floor(m/60);if(h<24)return `منذ ${h} س`;return `منذ ${Math.floor(h/24)} ي`}
function isDashboard(){return $('[data-view="dashboard"]')?.classList.contains('active')!==false&&!!$('.v8-main')}
function stateStats(s){const tasks=s.tasks||[],employees=s.employees||[],projects=s.projects||[];const active=tasks.filter(t=>['WORKING','RESEARCHING','REVIEWING'].includes(t.status));const waiting=tasks.filter(t=>t.status==='WAITING_FOR_NAWAF');const done=tasks.filter(t=>t.status==='COMPLETED');const blocked=tasks.filter(t=>t.blockedReason&&t.status!=='COMPLETED');const urgent=tasks.filter(t=>t.priority==='URGENT'&&t.status!=='COMPLETED');const busyEmployees=employees.filter(e=>['WORKING','RESEARCHING','REVIEWING'].includes(e.status));const completion=tasks.length?Math.round(done.length/tasks.length*100):0;return {tasks,employees,projects,active,waiting,done,blocked,urgent,busyEmployees,completion}}
function projectHealth(p,s){const ts=(s.tasks||[]).filter(t=>t.projectId===p.id),bad=ts.filter(t=>t.blockedReason||t.status==='WAITING_FOR_NAWAF').length,active=ts.filter(t=>['WORKING','RESEARCHING','REVIEWING'].includes(t.status)).length,done=ts.filter(t=>t.status==='COMPLETED').length;let score=100;if(bad)score-=Math.min(55,bad*18);if(ts.length&&!done&&!active)score-=12;if(p.status==='PAUSED')score=55;return {score:Math.max(0,score),bad,active,done,total:ts.length}}
function priority(s){const weight=t=>(t.status==='WAITING_FOR_NAWAF'?100:0)+(t.blockedReason?70:0)+(t.priority==='URGENT'?60:t.priority==='HIGH'?30:0)+(['WORKING','RESEARCHING','REVIEWING'].includes(t.status)?20:0)+(Date.parse(t.createdAt||'')?Math.min(20,(Date.now()-Date.parse(t.createdAt))/36e5):0);return [...(s.tasks||[])].filter(t=>t.status!=='COMPLETED').sort((a,b)=>weight(b)-weight(a)).slice(0,5)}
function employeeLoad(e,s){const active=(s.tasks||[]).filter(t=>t.employeeId===e.id&&['READY','WORKING','RESEARCHING','REVIEWING','WAITING_FOR_NAWAF'].includes(t.status));const working=active.filter(t=>['WORKING','RESEARCHING','REVIEWING'].includes(t.status)).length;return {count:active.length,working,load:Math.min(100,active.length*24+working*22)}}
function quickAction(label,action,kind=''){return `<button type="button" class="v14-quick ${kind}" data-v14-action="${action}"><span>${esc(label)}</span><small>فتح مباشر</small></button>`}
function render(){if(!isDashboard())return;const main=$('.v8-main');if(!main)return;let root=$('.v14-dashboard');if(!root){root=document.createElement('section');root.className='v14-dashboard';const anchor=$('.v9-control-strip')||$('.v8-stats')||main.firstElementChild;if(anchor)anchor.insertAdjacentElement('afterend',root);else main.prepend(root)}const s=read(),x=stateStats(s),prio=priority(s),activity=(s.activity||[]).slice(0,6),decisionCount=x.waiting.length,systemCloud=window.HQCloud?.status?.()||{};
root.innerHTML=`
<div class="v14-hero">
  <div><span class="v14-eyebrow">CEO OVERVIEW</span><h2>صورة الشركة الآن</h2><p>أهم ما يحتاج انتباهك بدون التنقل بين الأقسام.</p></div>
  <div class="v14-score"><strong>${x.completion}%</strong><span>نسبة إنجاز المهام</span></div>
</div>
<div class="v14-kpis">
 <button data-v14-go="tasks"><b>${x.active.length}</b><span>تعمل الآن</span><small>${x.busyEmployees.length} موظف نشط</small></button>
 <button data-v14-action="decisions"><b>${decisionCount}</b><span>قرارات تنتظرك</span><small>${decisionCount?'تحتاج مراجعتك':'ما فيه شيء معلق'}</small></button>
 <button data-v14-go="tasks"><b>${x.urgent.length}</b><span>مهام عاجلة</span><small>${x.blocked.length} متعثرة</small></button>
 <button data-v14-go="reports"><b>${x.done.length}</b><span>مكتمل</span><small>${x.tasks.length} إجمالي المهام</small></button>
 <button data-v14-go="workforce"><b>${x.employees.length}</b><span>فريق العمل</span><small>${x.employees.length-x.busyEmployees.length} متاح</small></button>
 <button data-v14-action="sync"><b>${systemCloud.cloud===false?'!':'✓'}</b><span>المزامنة</span><small>${systemCloud.dirty?'تغييرات بانتظار الحفظ':'الحالة مستقرة'}</small></button>
</div>
<div class="v14-grid">
 <article class="v14-card v14-priority"><header><div><span>FOCUS</span><h3>أولوياتك الآن</h3></div><button data-v14-go="tasks">كل المهام</button></header><div>${prio.length?prio.map((t,i)=>`<button class="v14-priority-row" data-v14-task="${esc(t.id)}"><em>${i+1}</em><span><b>${esc(t.title)}</b><small>${esc(t.blockedReason||t.status||'READY')} ${age(t.createdAt)?'• '+age(t.createdAt):''}</small></span><i class="${t.priority==='URGENT'?'hot':''}">${esc(t.priority||'NORMAL')}</i></button>`).join(''):'<div class="v14-empty">ما عندك أولويات معلقة حالياً.</div>'}</div></article>
 <article class="v14-card"><header><div><span>PROJECT HEALTH</span><h3>صحة المشاريع</h3></div><button data-v14-go="projects">المشاريع</button></header><div class="v14-project-health">${(s.projects||[]).map(p=>{const h=projectHealth(p,s);return `<button data-v14-project="${esc(p.id)}"><div><b>${esc(p.name)}</b><small>${h.total} مهام • ${h.active} تعمل • ${h.bad} تحتاج انتباه</small></div><div class="v14-meter"><span style="width:${h.score}%"></span></div><strong>${h.score}%</strong></button>`}).join('')||'<div class="v14-empty">ما فيه مشاريع.</div>'}</div></article>
 <article class="v14-card"><header><div><span>TEAM LOAD</span><h3>ضغط الموظفين</h3></div><button data-v14-go="workforce">الفريق</button></header><div class="v14-team-load">${(s.employees||[]).slice(0,8).map(e=>{const l=employeeLoad(e,s);return `<button data-v14-employee="${esc(e.id)}"><span class="v14-mini-avatar">${esc((e.name||'AI').slice(0,1))}</span><div><b>${esc(e.name)}</b><small>${esc(e.role||e.department||'موظف AI')} • ${l.count} مهام مفتوحة</small><div class="v14-load"><span style="width:${l.load}%"></span></div></div><strong>${l.load<35?'خفيف':l.load<70?'متوسط':'مرتفع'}</strong></button>`}).join('')}</div></article>
 <article class="v14-card"><header><div><span>LIVE ACTIVITY</span><h3>آخر النشاط</h3></div><button data-v14-action="activity">السجل</button></header><div class="v14-activity">${activity.length?activity.map(a=>`<div><span></span><p><b>${esc(a.text||'نشاط')}</b><small>${age(a.at)}</small></p></div>`).join(''):'<div class="v14-empty">ما فيه نشاط محفوظ.</div>'}</div></article>
</div>
<div class="v14-quickbar">
 <div><span>QUICK ACTIONS</span><b>نفّذ بسرعة</b></div>
 ${quickAction('أمر سريع','quick','gold')}
 ${quickAction('مهمة جديدة','new-task')}
 ${quickAction('محلل مالي','finance')}
 ${quickAction('قراراتي','decisions')}
 ${quickAction('تطبيقاتي','apps')}
</div>`;
bind(root)}
function bind(root){root.querySelectorAll('[data-v14-go]').forEach(b=>b.onclick=()=>document.querySelector(`[data-view="${b.dataset.v14Go}"]`)?.click());root.querySelectorAll('[data-v14-task]').forEach(b=>b.onclick=()=>document.querySelector(`[data-task="${CSS.escape(b.dataset.v14Task)}"]`)?.click());root.querySelectorAll('[data-v14-project]').forEach(b=>b.onclick=()=>document.querySelector(`[data-project="${CSS.escape(b.dataset.v14Project)}"]`)?.click());root.querySelectorAll('[data-v14-employee]').forEach(b=>b.onclick=()=>document.querySelector(`[data-employee="${CSS.escape(b.dataset.v14Employee)}"]`)?.click());root.querySelectorAll('[data-v14-action]').forEach(b=>b.onclick=async()=>{const a=b.dataset.v14Action;if(a==='quick')document.querySelector('[data-v9-quick]')?.click();else if(a==='new-task')document.querySelector('[data-action="new-task"]')?.click();else if(a==='finance')window.NawafFinance?.open?.();else if(a==='decisions')window.NawafHQV13?.openCenter?.();else if(a==='activity')window.NawafHQV12?.openActivity?.();else if(a==='apps')location.href='apps.html';else if(a==='sync'){b.disabled=true;try{await window.HQCloud?.pull?.();render()}finally{setTimeout(()=>b.disabled=false,600)}}})}
let timer;function schedule(){clearTimeout(timer);timer=setTimeout(render,120)}const obs=new MutationObserver(schedule);function boot(){obs.observe(document.body,{childList:true,subtree:true});window.addEventListener('nawaf:state-updated',schedule);setInterval(()=>{if(!document.hidden)render()},15000);render()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();window.NawafHQV14={render};
})();